// 1. Aserción de estado HTTP
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Aserción de contenido y estructura de respuesta
pm.test("Validar estructura de la respuesta JSON", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an("array");
    pm.expect(jsonData.length).to.be.above(0);
    pm.expect(jsonData[0]).to.have.property("id");
    pm.expect(jsonData[0]).to.have.property("customerId");
    pm.expect(jsonData[0]).to.have.property("type");
    pm.expect(jsonData[0]).to.have.property("balance");
});

// 3. Verificación de datos del negocio
pm.test("Regla de negocio: Cuenta activa asociada al cliente con saldo válido", function () {
    var jsonData = pm.response.json();
    var customerIdEsperado = Number(pm.environment.get("customerId"));

    pm.expect(jsonData[0].customerId).to.eql(customerIdEsperado);
    pm.expect(jsonData[0].type).to.eql("CHECKING");
    pm.expect(jsonData[0].balance).to.be.a("number");

    // Guarda el ID de cuenta real en el entorno para encadenar la siguiente petición
    pm.environment.set("accountId", jsonData[0].id);
});

// 1. Aserción de estado HTTP
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Aserción de contenido y estructura de respuesta
pm.test("Validar estructura del listado de transacciones", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an("array");
    pm.expect(jsonData.length).to.be.above(0);

    var ultimaTransaccion = jsonData[jsonData.length - 1];
    pm.expect(ultimaTransaccion).to.have.property("id");
    pm.expect(ultimaTransaccion).to.have.property("accountId");
    pm.expect(ultimaTransaccion).to.have.property("type");
    pm.expect(ultimaTransaccion).to.have.property("date");
    pm.expect(ultimaTransaccion).to.have.property("amount");
    pm.expect(ultimaTransaccion).to.have.property("description");
});

// 3. Verificación de datos del negocio
pm.test("Regla de negocio: Movimiento corresponde a la cuenta y registra el débito del pago", function () {
    var jsonData = pm.response.json();
    var accountIdEsperado = Number(pm.environment.get("accountId"));
    var ultimaTransaccion = jsonData[jsonData.length - 1];

    pm.expect(ultimaTransaccion.accountId).to.eql(accountIdEsperado);
    pm.expect(ultimaTransaccion.type).to.eql("Debit");
    pm.expect(ultimaTransaccion.amount).to.be.above(0);
    pm.expect(ultimaTransaccion.description).to.include("Bill Payment");
});
